table ip vpnnat {
	chain post {
		type nat hook postrouting priority srcnat; policy accept;
		ip saddr 10.9.10.0/24 oifname "eth3" masquerade
		ip saddr 10.9.11.0/24 oifname "eth4" masquerade
	}
}
table inet vpnfw {
	chain vpnforward {
		type filter hook forward priority filter - 10; policy accept;
		ip saddr 10.9.10.0/24 ip daddr != 10.11.0.0/24 drop
		ip saddr 10.9.11.0/24 ip daddr != 10.12.0.0/24 drop
	}
}
